actions.script:
ec.message.pushErrors()
let found = null
try {
    found = ec.service.sync().name('mantle.humanres.PeopleServices.get#EmploymentLetter')
        .parameters({employmentChangeId: employmentChangeId || ''}).requireNewTransaction(true).call() || null
    if (ec.message.hasError()) found = null
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
const enc = text => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const L = text => enc(ec.l10n.localize(text))
printHtml = !found ? '<p>' + L('This employment change is not available') + '</p>'
    : found.issued ? '<p>' + L('This letter is issued: open it as it was stored, from the employee record') + '</p>'
    : !found.offered ? '<p>' + enc(found.problem) + '</p>'
    : found.letterHtml
printUrl = '/apps/People/Employees/EmploymentLetter?renderMode=html-print&employmentChangeId=' + encodeURIComponent(employmentChangeId || '')
